mapper.update:
UPDATE agent_event_outbox
SET claim_owner = #{claimOwner}, claimed_until = #{claimedUntil},
    publish_attempts = publish_attempts + 1
WHERE published_at IS NULL
  AND dead_lettered_at IS NULL
  AND created_at <= #{claimBefore}
  AND next_attempt_at <= #{now}
  AND (claim_owner IS NULL OR claimed_until < #{now})
ORDER BY id ASC
LIMIT #{limit}

mapper.select:
SELECT id, schema_version, task_id, thread_id, sequence_no, event_id, turn_no,
       event_type, status, payload_json, error_message, duration_ms, published_at, created_at
FROM agent_event_outbox
WHERE published_at IS NULL AND dead_lettered_at IS NULL AND claim_owner = #{claimOwner}
ORDER BY id ASC
LIMIT #{limit}

