UPDATE agent_event_outbox
SET published_at = #{publishedAt}, claim_owner = NULL, claimed_until = NULL, last_error = NULL
WHERE id = #{id} AND published_at IS NULL AND claim_owner = #{claimOwner}

UPDATE agent_event_outbox
SET claim_owner = NULL, claimed_until = NULL, next_attempt_at = #{nextAttemptAt},
    last_error = #{lastError}
WHERE id = #{id} AND published_at IS NULL AND claim_owner = #{claimOwner}

UPDATE agent_event_outbox
SET claim_owner = NULL, claimed_until = NULL, dead_lettered_at = #{deadLetteredAt},
    last_error = #{lastError}
WHERE id = #{id} AND published_at IS NULL AND claim_owner = #{claimOwner}
